package kz.zeroops.agent;
import java.time.Instant; import java.util.Set; import org.springframework.stereotype.Component;
/** Rejects any execution input outside the signed-manifest allowlist. */
@Component public class AgentBoundary { private static final Set<String> RUNTIMES=Set.of("NODE","SPRING_BOOT","DOCKERFILE"); public boolean accepts(Manifest m){return m!=null&&RUNTIMES.contains(m.runtime())&&m.expiresAt().isAfter(Instant.now())&&m.repositoryUrl().matches("https://github\\.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+/?")&&m.branch().matches("[A-Za-z0-9._/-]{1,255}")&&m.commitSha().matches("[A-Fa-f0-9]{7,64}")&&m.healthPath().matches("/[A-Za-z0-9._~/%?-]{0,255}")&&m.applicationPort()>0&&m.applicationPort()<65536&&m.publicPort()>=1024&&m.publicPort()<65536&&m.imageTag().matches("[a-z0-9._/-]+:[a-f0-9]{7,64}")&&!m.rawCommand();} public record Manifest(String deploymentId,String projectId,String serverId,String repositoryUrl,String branch,String commitSha,String runtime,int applicationPort,int publicPort,String healthPath,String imageTag,Instant expiresAt,boolean rawCommand){} }
